#[cfg(test)]
mod tests {
    /// A mesma chave nas duas tabelas: a daqui valeria por cima da principal.
    #[test]
    fn sem_chaves_repetidas() {
        let dup: Vec<&str> = super::T.iter().map(|r| r[0]).filter(|k| super::super::T.iter().any(|m| m[0] == *k)).collect();
        assert!(dup.is_empty(), "repetidas na tabela principal: {dup:?}");
        let mut seen = std::collections::HashSet::new();
        let twice: Vec<&str> = super::T.iter().map(|r| r[0]).filter(|k| !seen.insert(*k)).collect();
        assert!(twice.is_empty(), "repetidas aqui: {twice:?}");
    }
}
